#!/usr/bin/env python3
"""Export the C allowlist, not a separately maintained browser policy."""
import json
from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
header = (root / "src/policy.h").read_text()
names = re.findall(r"X\((\w+)\)", header)
assert names and len(names) == len(set(names))
out = (
    "// Generated by tools/export-policy.py from src/policy.h.\nexport const allowed = Object.freeze("
    + json.dumps(sorted(names), indent=2)
    + ");\n"
)
(root / "docs/policy.js").write_text(out)
